def is_valid_datetime(date_string):
    """
    Validates if a string is in datetime format.
    """
    try:
        datetime.fromisoformat(date_string.replace('Z', '+00:00'))
        return True
    except ValueError:
        return False

def validate_response_schema(response_data):
    """
    Validates that the response matches the specified API schema.
    """
    required_fields = ["public-key", "type", "fingerprint", "preferred", "created-at"]
    for field in required_fields:
        assert field in response_data, f"Response is missing field: {field}"

